import{_ as e,c as i,o as t,a2 as r}from"./chunks/framework.mqLGQ42V.js";const u=JSON.parse('{"title":"AI 代理 (AI Agent) - Rive 脚本","description":"脚本 (Scripting) 在 Rive 中使用 AI 代理增强交互体验。","frontmatter":{"title":"AI 代理 (AI Agent) - Rive 脚本","description":"脚本 (Scripting) 在 Rive 中使用 AI 代理增强交互体验。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 脚本, AI 代理"}]]},"headers":[],"relativePath":"scripting/ai-agent.md","filePath":"scripting/ai-agent.md","lastUpdated":1774838907000}'),l={name:"scripting/ai-agent.md"};function o(n,a,h,s,d,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<p>脚本 (Scripting)</p><h1 id="ai-代理-ai-agent" tabindex="-1">AI 代理 (AI Agent) <a class="header-anchor" href="#ai-代理-ai-agent" aria-label="Permalink to &quot;AI 代理 (AI Agent)&quot;">​</a></h1><p>在 Rive 中使用 AI 代理增强交互体验。</p><h2 id="​-概览" tabindex="-1"><a href="#overview">​</a> 概览 <a class="header-anchor" href="#​-概览" aria-label="Permalink to &quot;[​](#overview) 概览&quot;">​</a></h2><p>Rive AI 代理允许你将 AI 能力集成到 Rive 动画中，创建更智能的交互体验。</p><h2 id="​-mcp-集成" tabindex="-1"><a href="#mcp-integration">​</a> MCP 集成 <a class="header-anchor" href="#​-mcp-集成" aria-label="Permalink to &quot;[​](#mcp-integration) MCP 集成&quot;">​</a></h2><p>Rive 支持 Model Context Protocol (MCP)，让 AI 助手能够直接与 Rive 编辑器交互。</p><p>有关 MCP 的详细信息，请参阅 <a href="/docs/editor/mcp">MCP 页面</a>。</p><h2 id="​-使用场景" tabindex="-1"><a href="#use-cases">​</a> 使用场景 <a class="header-anchor" href="#​-使用场景" aria-label="Permalink to &quot;[​](#use-cases) 使用场景&quot;">​</a></h2><h3 id="智能角色" tabindex="-1">智能角色 <a class="header-anchor" href="#智能角色" aria-label="Permalink to &quot;智能角色&quot;">​</a></h3><ul><li>角色对用户输入做出智能响应</li><li>基于上下文调整表情和动作</li></ul><h3 id="动态内容" tabindex="-1">动态内容 <a class="header-anchor" href="#动态内容" aria-label="Permalink to &quot;动态内容&quot;">​</a></h3><ul><li>AI 生成的文本动态显示</li><li>根据用户意图调整动画</li></ul><h3 id="辅助功能" tabindex="-1">辅助功能 <a class="header-anchor" href="#辅助功能" aria-label="Permalink to &quot;辅助功能&quot;">​</a></h3><ul><li>语音到动画的转换</li><li>智能手势识别</li></ul><h2 id="​-入门" tabindex="-1"><a href="#getting-started">​</a> 入门 <a class="header-anchor" href="#​-入门" aria-label="Permalink to &quot;[​](#getting-started) 入门&quot;">​</a></h2><ol><li>确保你的 Rive 文件设置了适当的状态机</li><li>使用数据绑定连接 AI 输出到动画属性</li><li>在运行时通过 API 接入 AI 服务</li></ol><h2 id="​-资源" tabindex="-1"><a href="#resources">​</a> 资源 <a class="header-anchor" href="#​-资源" aria-label="Permalink to &quot;[​](#resources) 资源&quot;">​</a></h2><ul><li><a href="/docs/editor/mcp">MCP 集成</a></li><li><a href="/docs/editor/data-binding/overview">数据绑定</a></li><li><a href="/docs/editor/state-machine/overview">状态机</a></li></ul>',19)])])}const m=e(l,[["render",o]]);export{u as __pageData,m as default};
